import {supportOrderLabel} from './expedition-support-priority.mjs';
import {attackOrderLabel} from './expedition-position-priority.mjs';
import {HEROES,SKILLS,POS,DEFENSES,EXPEDITIONS,trainingOptions,roomsFor,resolveHeroPlan,clone} from './expedition-data.mjs';
import {equipmentName} from './expedition-equipment.mjs';import {ADVANCEMENTS} from './expedition-advancement-data.mjs';
export function lineupChanges(before,after){
 const snapshot=(hero,config)=>{const def=HEROES.find(h=>h.id===hero.id);return clone({id:hero.id,name:def.name,role:def.role,classId:def.classId,settings:hero,rooms:roomsFor(config).map(room=>({id:room.id,name:room.name,plan:resolveHeroPlan(hero,room.id)}))});};
 return {beforeRoute:before.expedition,afterRoute:after.expedition,left:before.heroes.filter(h=>!after.heroes.some(u=>u.id===h.id)).map(h=>snapshot(h,before)),joined:after.heroes.filter(h=>!before.heroes.some(u=>u.id===h.id)).map(h=>snapshot(h,after))};
}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const commands=rows=>rows.map(r=>`${SKILLS[r.skill].name} → ${POS[r.target]||{self:'自身',all:'全队',healer:'治疗者',summoner:'召唤者',priority:'按个人阵位优先',supportPriority:'按辅助阵位优先'}[r.target]}（${{round:'每回合一次',repeat:'持续',once:'一次',cycle:'轮转'}[r.mode]}）`).map(esc).join('；')||'无';
export function lineupChangesView(diff,mode='draft'){
 if(!diff.left.length&&!diff.joined.length)return '';
 const card=h=>{const s=h.settings,training=Object.entries(s.training).filter(([,n])=>n>0).map(([key,n])=>trainingOptions(h.id)[key].name+'+'+n).map(esc).join('、')||'未培养';return `<article class="lineup-diff-card" data-lineup-member="${h.id}"><h4>${esc(h.name)} · ${esc(h.role)}</h4><p>站位 ${POS[s.pos]} · ${esc(equipmentName(s.gear))}</p><p>永久训练：${training}</p><p>技能专修 ${SKILLS[s.trained].name} · 防御专修 ${DEFENSES[s.defenseFocus].name}</p><p>后期进阶：${s.advancement?ADVANCEMENTS[s.advancement].name:'未选择'}</p><p><b>默认预备</b> ${commands(s.prep)}</p>${s.prep.some(r=>r.target==='supportPriority')?`<p>辅助优先 ${supportOrderLabel(s)}</p>`:''}<p><b>默认普通</b> ${commands(s.main)}</p>${s.main.some(r=>r.target==='priority')?`<p>远攻优先 ${attackOrderLabel(s)}</p>`:''}<details class="lineup-room-plans"><summary>逐房实际配置 · ${h.rooms.length}房</summary>${h.rooms.map(r=>`<div><h5>${esc(r.name)} · ${POS[r.plan.pos]}</h5><p>预备 ${commands(r.plan.prep)}</p>${r.plan.prep.some(row=>row.target==='supportPriority')?`<p>辅助优先 ${supportOrderLabel(r.plan)}</p>`:''}<p>普通 ${commands(r.plan.main)}</p>${r.plan.main.some(row=>row.target==='priority')?`<p>远攻优先 ${attackOrderLabel(r.plan)}</p>`:''}<p>救护 ${r.plan.healing.enabled?'≤'+Math.round(r.plan.healing.threshold*100)+'% / '+(POS[r.plan.healing.target]||{all:'全队',self:'自身'}[r.plan.healing.target]):'停用'}</p></div>`).join('')}</details></article>`;};
 return `<section class="lineup-diff"><h3>出战名单变化 · 离队${diff.left.length} / 入队${diff.joined.length}</h3><p>分别展示双方各自配置，不表示资产转移或角色优劣。历史配置未记录的经验和课程费用不补推；两份方案的默认与逐房指令分别核对。</p><div class="lineup-diff-grid"><div class="lineup-left"><h4>离队 · 历史出征快照</h4><p>${EXPEDITIONS[diff.beforeRoute].name}</p>${diff.left.map(card).join('')||'<p>无</p>'}</div><div class="lineup-joined"><h4>入队 · ${mode==='guild'?'当前公会资产与战术':'当前准备草稿'}快照</h4><p>${EXPEDITIONS[diff.afterRoute].name}</p>${diff.joined.map(card).join('')||'<p>无</p>'}</div></div></section>`;
}
